create or replace function pg_temp.denied(statement text)returns boolean language plpgsql as $$begin execute statement;return false;exception when others then return true;end$$;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"85000000-0000-4000-8000-000000000002","role":"authenticated"}',true);select is((select count(*)from public.import_batches),0::bigint,'team member sees no import history');select ok(pg_temp.denied($$select public.create_import_preview('85000000-0000-4000-8000-000000000010','x.json',repeat('0',64),'{}','v','{}','[]')$$),'unauthorized importer denied');
select set_config('request.jwt.claims','{"sub":"85000000-0000-4000-8000-000000000003","role":"authenticated"}',true);select ok(pg_temp.denied($$select public.create_import_preview('85000000-0000-4000-8000-000000000010','x.json',repeat('0',64),'{}','v','{}','[]')$$),'inactive importer denied');
select set_config('request.jwt.claims','{"sub":"85000000-0000-4000-8000-000000000001","role":"authenticated"}',true);select ok(pg_temp.denied($$select public.create_import_preview('85000000-0000-4000-8000-000000000020','x.json',repeat('0',64),'{}','v','{}','[]')$$),'cross-organization target denied');select ok(pg_temp.denied($$select public.create_import_preview('85000000-0000-4000-8000-000000000010','forged.json',repeat('0',64),'{}','v','{}','[]')$$),'forged digest denied');
select lives_ok($$select public.create_import_preview('85000000-0000-4000-8000-000000000010','valid.json',encode(extensions.digest(convert_to('{"test":"valid"}','UTF8'),'sha256'),'hex'),'{"test":"valid"}','aftifestCommandData/export-v1','{"counts":{"departments":1,"sponsors":1,"decisions":1},"warnings":["SAMPLE / UNAPPROVED"]}','[{"sourceType":"departments","sourceKey":"departments:1","targetType":"department","payload":{"id":1,"name":"Imported TEST Department","progress":99},"mapping":{},"status":"ready","notes":"SAMPLE / UNAPPROVED"},{"sourceType":"sponsors","sourceKey":"sponsors:1","targetType":"sponsor","payload":{"organization":"Illustrative Sponsor","value":999999},"mapping":{},"status":"ready","notes":"SAMPLE / UNAPPROVED"},{"sourceType":"decisions","sourceKey":"decisions:1","targetType":"decision","payload":{"title":"Illustrative Decision"},"mapping":{},"status":"ready","notes":"SAMPLE / UNAPPROVED"}]')$$,'authorized preview created');
select is((select count(*)from public.import_batches),1::bigint,'admin reads own organization import history');select lives_ok($$select public.create_import_preview('85000000-0000-4000-8000-000000000010','duplicate.json',encode(extensions.digest(convert_to('{"test":"valid"}','UTF8'),'sha256'),'hex'),'{"test":"valid"}','aftifestCommandData/export-v1','{}','[]')$$,'duplicate preview safely reuses batch');select is((select count(*)from public.import_batches),1::bigint,'duplicate digest creates no second batch');
select lives_ok($$select public.execute_import_batch((select id from public.import_batches limit 1))$$,'transactional import completes');select is((select count(*)from public.departments where import_batch_id is not null),1::bigint,'valid department imported once');select is((select estimated_value from public.sponsors where import_batch_id is not null),null::numeric,'illustrative sponsor value not imported');select is((select status from public.decisions where import_batch_id is not null),'draft','prototype decision remains draft');select ok((select approval_required=false and verification_status='sample_unapproved' from public.decisions where import_batch_id is not null),'imported governance stays unapproved and outside approval workflow');select lives_ok($$select public.execute_import_batch((select id from public.import_batches limit 1))$$,'repeat execution is idempotent');select is((select count(*)from public.departments where import_batch_id is not null),1::bigint,'repeat import creates no duplicates');
reset role;insert into public.import_batches(id,organization_id,filename,source_digest,schema_version,raw_payload,status,uploaded_by)values('85000000-0000-4000-8000-000000000090','85000000-0000-4000-8000-000000000010','failure.json',repeat('f',64),'test','{}','ready','85000000-0000-4000-8000-000000000001');insert into public.import_items(organization_id,batch_id,source_type,source_record_key,target_type,source_payload,reconciliation_status)values('85000000-0000-4000-8000-000000000010','85000000-0000-4000-8000-000000000090','test','test:1','unsupported','{}','ready');set local role authenticated;select set_config('request.jwt.claims','{"sub":"85000000-0000-4000-8000-000000000001","role":"authenticated"}',true);select lives_ok($$select public.execute_import_batch('85000000-0000-4000-8000-000000000090')$$,'forced failure is contained');select is((select status from public.import_batches where id='85000000-0000-4000-8000-000000000090'),'rolled_back','failed batch records rolled-back lifecycle');select ok(pg_temp.denied($$update public.import_batches set status='completed'$$),'ordinary client cannot rewrite import history');reset role;select ok(exists(select 1 from public.audit_events where action='import.import_batches.update'),'import lifecycle is audited');select*from finish();rollback;
